//! Disposable microbenchmark of the existing String equality operation.
#[path = "../tests/support/oop.rs"]
mod oop;
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let yes = h.named(b"true").unwrap();
    let no = h.named(b"false").unwrap();
    let selector = q.keep(h.intern(b"=").unwrap()).unwrap();
    for length in [16, 4096, 1048576] {
        let bytes = vec![b'x'; length];
        let left = q.string(&bytes).unwrap();
        let equal = q.string(&bytes).unwrap();
        let mut first = bytes.clone(); first[0] = b'y';
        let mut last = bytes; last[length - 1] = b'y';
        let first = q.string(&first).unwrap();
        let last = q.string(&last).unwrap();
        let calls = if length == 1048576 { 2000 } else { 200000 };
        for (name, right, expected) in [("equal", equal, yes), ("same", left, yes), ("first", first, no), ("last", last, no)] {
            let args = [right];
            for _ in 0..100 { assert_eq!(unsafe { h.id.send(left, selector, &args).unwrap() }, expected); }
            for _ in 0..5 {
                let start = unsafe { clock_gettime_nsec_np(16) };
                for _ in 0..calls { assert_eq!(unsafe { h.id.send(left, selector, &args).unwrap() }, expected); }
                println!("{length} {name} {calls} {}", unsafe { clock_gettime_nsec_np(16) } - start);
            }
        }
    }
}
